            EnumSet<Usage> usage,
            boolean mcpEnabledByDefault,
            Class<?> bean,
            boolean blocking,
            boolean nonBlocking) {
        super(methodName, description, parameters, usage, mcpEnabledByDefault);
        this.bean = bean;
        this.blocking = blocking;
        this.nonBlocking = nonBlocking;
    }

    public Class<?> getBean() {
        return bean;
