        if (hub != null) {
            for (SubscriptionKey key : new ArrayList<>(locals.keySet())) {
                hub.unsubscribe(key, this);
            }
        }
        locals.clear();
        pending.clear();
        scheduled.set(false);
    }

    /** Whether this session's subscriptions are closed (test hook). */
    boolean isClosed() {
        return closed.get();
    }
