package dev.pathland.server.introspection;

import java.util.List;

/**
 * Immutable, read-only snapshots of the live Pathland runtime, used by diagnostic
 * tooling (the Quarkus Dev UI). Snapshots are built on each registry's actor thread,
 * so they observe the same state the emitter does; they never expose the mutable
 * session, tree, or emitter internals.
 *
 * <p>This is a development/diagnostic surface. It carries no control flow and no
 * business state of its own.
 */
public final class PathlandIntrospection {

    private PathlandIntrospection() {
    }

    /** The whole host: every mounted app and its live sessions. */
    public record HostSnapshot(
            boolean running,
            int activeSessions,
            List<RegistrySnapshot> mounts) {
    }

    /** One mounted app (registry): its framework base, flags, and live sessions. */
    public record RegistrySnapshot(
            String mount,
            String base,
            boolean debugHtml,
            boolean serviceWorker,
            int activeSessions,
            List<SessionSnapshot> sessions) {
    }

    /** One live (or mount-only) session. */
    public record SessionSnapshot(
            String id,
            String mount,
            String stateScope,
            String route,
            float viewportWidth,
            float viewportHeight,
            boolean connected,
            boolean closed,
            long openedAtMillis,
            long lastActivityMillis,
            int rootId,
            int treeNodes,
            int proxyCount,
            List<SubscriptionSnapshot> subscriptions,
            SessionStats stats) {
    }

    /** One topic subscription held by a session. */
    public record SubscriptionSnapshot(String topic, String subject, boolean pending) {
    }

    /** Per-session throughput counters. */
    public record SessionStats(
            long inboundEvents,
            long resyncs,
            long batchesSent,
            int lastFrames,
            int lastOpcodes,
            int lastBytes,
            int sequence) {
    }
}

package dev.pathland.server;

/**
 * Read-only build/asset information for diagnostic tooling (the Quarkus Dev UI):
 * the content-hashed DOM client bundle the SSR document references and its SRI
 * digest. Resolved from the same manifest the renderer uses, so the Dev UI shows
 * exactly what the browser is told to load.
 */
public final class PathlandBuildInfo {

    private PathlandBuildInfo() {
    }

    /** The current DOM client bundle filename (e.g. {@code dom-renderer-<hash>.js}). */
    public static String domBundleName() {
        return PathlandAssets.bundleName();
    }

    /** The bundle's Subresource Integrity digest ({@code sha384-…}), or empty. */
    public static String domBundleIntegrity() {
        return PathlandAssets.bundleIntegrity();
    }
}

