package dev.pathland.quarkus.devui;

import dev.pathland.server.PathlandBuildInfo;
import dev.pathland.server.PathlandHost;
import dev.pathland.server.PathlandRegistry;
import dev.pathland.server.introspection.PathlandIntrospection.HostSnapshot;
import dev.pathland.server.introspection.PathlandIntrospection.RegistrySnapshot;
import dev.pathland.server.introspection.PathlandIntrospection.SessionSnapshot;
import io.quarkus.runtime.annotations.JsonRpcDescription;
import io.quarkus.runtime.annotations.JsonRpcUsage;
import io.quarkus.runtime.annotations.Usage;
import jakarta.inject.Inject;

import java.util.ArrayList;
import java.util.List;

/**
 * The runtime side of the Pathland Dev UI: read-only snapshots plus a small set of
 * lifecycle actions (resync, close). Registered as an unremovable dev-mode bean by
 * {@code PathlandDevUiProcessor}; never discovered (or instantiated) outside local
 * development.
 *
 * <p>All reads go through {@link PathlandHost#snapshot()}, which runs on each
 * registry's actor. Actions reuse the registry's own actor-safe lifecycle
 * operations, so the Dev UI never mutates a session off-actor.
 */
public class PathlandDevUiRpc {

    @Inject
    PathlandHost host;

    /** For tests / direct construction (CDI uses the no-arg constructor + field injection). */
    PathlandDevUiRpc(PathlandHost host) {
        this.host = host;
    }

    public PathlandDevUiRpc() {
    }

    /** The host overview: mounts, live session count, and the assets the SSR references. */
    @JsonRpcDescription("Pathland host overview: mounted apps, live sessions, and build assets")
    @JsonRpcUsage(Usage.DEV_UI)
    public Overview overview() {
        HostSnapshot snapshot = host.snapshot();
        List<MountSummary> mounts = new ArrayList<>(snapshot.mounts().size());
        for (RegistrySnapshot mount : snapshot.mounts()) {
            mounts.add(new MountSummary(
                    mount.mount(),
                    mount.base(),
                    mount.activeSessions(),
                    mount.debugHtml(),
                    mount.serviceWorker()));
        }
        var renderer = dev.pathland.render.html.HtmlRenderer.tryInstance();
        String baseCss = renderer == null ? "" : renderer.baseCssName();
        return new Overview(
                snapshot.running(),
                snapshot.activeSessions(),
                List.copyOf(mounts),
                PathlandBuildInfo.domBundleName(),
                PathlandBuildInfo.domBundleIntegrity(),
                baseCss);
    }

    /** Every live session across every mount. */
    @JsonRpcDescription("List every live Pathland session across all mounted apps")
    @JsonRpcUsage(Usage.DEV_UI)
    public List<SessionSnapshot> sessions() {
        List<SessionSnapshot> sessions = new ArrayList<>();
        for (RegistrySnapshot mount : host.snapshot().mounts()) {
            sessions.addAll(mount.sessions());
        }
        return List.copyOf(sessions);
    }

    /** A one-line card summary: mounted apps and live sessions. */
    @JsonRpcDescription("A one-line summary of mounted apps and live sessions")
    @JsonRpcUsage(Usage.DEV_UI)
    public String overviewSummary() {
        HostSnapshot snapshot = host.snapshot();
        int apps = snapshot.mounts().size();
        int sessions = snapshot.activeSessions();
        return apps + (apps == 1 ? " app" : " apps") + " · "
                + sessions + (sessions == 1 ? " live session" : " live sessions");
    }

    /** The dynamic card label for the Sessions page. */
    @JsonRpcDescription("The number of live sessions")
    @JsonRpcUsage(Usage.DEV_UI)
    public String sessionsLabel() {
        return String.valueOf(host.activeSessions());
    }

    /** Re-send one session's current tree as a full snapshot ({@code META::RESYNC}). */
    @JsonRpcDescription("Re-send one session's current tree as a full snapshot")
    @JsonRpcUsage(Usage.DEV_UI)
    public ActionResult resync(String sessionId) {
        PathlandRegistry registry = registryFor(sessionId);
        if (registry == null) {
            return ActionResult.failure("unknown session: " + sessionId);
        }
        registry.resync(sessionId);
        return ActionResult.success();
    }

    /** Re-sync every live session. */
    @JsonRpcDescription("Re-send every live session's current tree as a full snapshot")
    @JsonRpcUsage(Usage.DEV_UI)
    public ActionResult resyncAll() {
        for (RegistrySnapshot mount : host.snapshot().mounts()) {
            PathlandRegistry registry = host.registry(mount.mount());
            if (registry == null) {
                continue;
            }
            for (SessionSnapshot session : mount.sessions()) {
                registry.resync(session.id());
            }
        }
        return ActionResult.success();
    }

    /** Close (and remove) one live session. */
    @JsonRpcDescription("Close and remove one live session")
    @JsonRpcUsage(Usage.DEV_UI)
    public ActionResult closeSession(String sessionId) {
        PathlandRegistry registry = registryFor(sessionId);
        if (registry == null) {
            return ActionResult.failure("unknown session: " + sessionId);
        }
        registry.close(sessionId);
        return ActionResult.success();
    }

    private PathlandRegistry registryFor(String sessionId) {
        if (sessionId == null || sessionId.isBlank()) {
            return null;
        }
        for (PathlandRegistry registry : host.registries()) {
            if (registry.hasSession(sessionId)) {
                return registry;
            }
        }
        return null;
    }

    public record Overview(
            boolean running,
            int activeSessions,
            List<MountSummary> mounts,
            String domBundle,
            String domIntegrity,
            String baseCss) {
    }

    public record MountSummary(
            String mount,
            String base,
            int activeSessions,
            boolean debugHtml,
            boolean serviceWorker) {
    }

    public record ActionResult(boolean ok, String error) {
        static ActionResult success() {
            return new ActionResult(true, null);
        }

        static ActionResult failure(String error) {
            return new ActionResult(false, error);
        }
    }
}

// The Pathland per-window-id service worker (issue #155).
//
// A top-level navigation is issued by the browser before any page JS runs, so the
// server cannot see the tab's `wid` (it lives in sessionStorage + the WebSocket URL,
// never in the page URL). This worker attaches it to navigations, so the SSR can
// render the right persisted-state scope on the first paint — without the id ever
// appearing in the address bar.
//
// It is strictly pass-through: it never caches responses and it fails open (any
// error -> the original request). Non-navigation requests are untouched.
//
// The id is keyed by the tab's client id, so two tabs never share a scope. The map
// lives in the Cache API (the worker is evicted when idle) and is seeded by the page
// on boot (`postMessage`) and carried across documents via `resultingClientId`.

const STORE = "pathland-sw";
const KEY_PREFIX = "/__pathland-wid/";

// The cache key must be an ABSOLUTE URL: Safari has thrown on a relative URL in the
// worker's Request constructor (and the throw used to be swallowed silently).
function widKey(clientId) {
  return new Request(new URL(KEY_PREFIX + clientId, self.location.origin).href);
}

async function remember(clientId, wid) {
  if (!clientId || !wid) return;
  try {
    const cache = await caches.open(STORE);
    await cache.put(widKey(clientId), new Response(wid));
  } catch (err) {
    // Best effort — but visible: a silent failure here means the SSR renders defaults.
    console.warn("[pathland] failed to remember the window id", err);
  }
}

async function recall(clientId) {
  if (!clientId) return null;
  try {
    const cache = await caches.open(STORE);
    const hit = await cache.match(widKey(clientId));
    return hit ? await hit.text() : null;
  } catch (err) {
    console.warn("[pathland] failed to recall the window id", err);
    return null;
  }
}

// Resolve the window id for a navigation. Chrome reports the *initiating document's*
// client id on the fetch event; WebKit leaves it EMPTY for navigations (it only sets
// `resultingClientId`, which names the document that does not exist yet), so we fall
// back to client identity only when it is unambiguous — never guess between tabs, as a
// wrong id would render another window's persisted state.
async function widFor(event) {
  if (event.clientId) return recall(event.clientId);
  const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
  if (windows.length === 1) return recall(windows[0].id);
  const sameUrl = windows.filter((client) => client.url === event.request.url);
  if (sameUrl.length === 1) return recall(sameUrl[0].id);
  return null; // ambiguous -> fail open (the SSR renders defaults, the live link corrects)
}

self.addEventListener("install", () => self.skipWaiting());

self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));

// The page registers its id on boot (belt-and-braces for the first, uncontrolled
// load — later navigations carry it via `resultingClientId`).
self.addEventListener("message", (event) => {
  const data = event.data;
  if (!data || data.type !== "pathland-wid") return;
  const clientId = event.source && event.source.id;
  event.waitUntil(remember(clientId, data.wid));
});

self.addEventListener("fetch", (event) => {
  if (event.request.mode !== "navigate") return; // pass everything else through
  event.respondWith((async () => {
    try {
      const wid = await widFor(event);
      if (!wid) return fetch(event.request); // fail open: no id -> the plain request
      const url = new URL(event.request.url);
      url.searchParams.set("wid", wid);
      // NEVER pass the navigation Request as the init: its `mode` is "navigate", which a
      // script cannot construct — fetch() would throw a TypeError and we would fall back
      // to the unscoped request (the "still flashes defaults" bug). Build an explicit
      // init instead. `cache: "reload"` keeps a same-window reload from being served a
      // stale SSR body out of the HTTP cache (the rewritten URL is its own cache key).
      const response = await fetch(url.toString(), {
        method: "GET",
        headers: event.request.headers,
        credentials: "same-origin",
        mode: "same-origin",
        redirect: "manual",
        cache: "reload",
      });
      // Carry the id to the next document in this tab, so a reload keeps resolving
      // even if the client id changes across documents.
      await remember(event.resultingClientId, wid);
      return response;
    } catch (err) {
      // Never break a navigation — but make a silent no-op visible (the SW's own
      // DevTools console context) instead of failing open invisibly.
      console.warn("[pathland] service worker navigation rewrite failed; loading unscoped", err);
      return fetch(event.request);
    }
  })());
});

