        _showSource: { state: true },
        _loading: { state: true }
    };

    constructor() {
        super();
        this._mount = '/';
        this._route = '/';
        this._html = '';
        this._error = null;
        this._showSource = false;
        this._loading = false;
    }

    connectedCallback() {
